\label{def:ironing}
    Given a distribution function $F(\cdot)$ and any function $\theta:\mathcal{V}\rightarrow\mathbb{R}$, the \textnormal{ironed virtual value function}, $\Bar{\theta}$, is constructed as follows:

    \begin{enumerate}
        \item For $q\in[0,1]$, define $h(q)=\theta\brackets{F^{-1}(q)}$.
        \item Define $H(q)=\int_0^q h(r)dr$.
        \item Define $\Psi$ as the convex hull of $H$ --- the largest convex function bounded above by $H$ for all $q\in[0,1]$.
        \item Define $\psi(q)$ as the derivative of $\Psi(q)$, where defined, and extend to all of $[0,1]$ by right-continuity.
        \item Finally, $\Bar{\theta}(v)=\psi(F(v))$.
    \end{enumerate}

\label{lemma:ironing-properties}
    Let $F$ be a distribution function, let $\theta:\mathcal{V}\rightarrow\mathbb{R}$, and let $\x{v}$ be a monotone allocation rule. 
    Define $\Psi,H$ and $\Bar{\theta}$ as in Definition~\ref{def:ironing}.
    Then 
    \begin{equation}
        \bb{E}\sqbr{\theta(v)\x{v}}\leq \bb{E}\sqbr{\Bar{\theta}(v)\x{v}},
    \end{equation}
    with equality holding if and only if $\frac{d}{d v}\x{v}=0$ wherever $\Psi(F(v))<H(F(v))$.

\begin{equation}
        \bb{E}\sqbr{\theta(v)\x{v}}\leq \bb{E}\sqbr{\Bar{\theta}(v)\x{v}},
    \end{equation}

